package org.eurorig.routing;
import static org.junit.Assert.*;import org.junit.Test;import java.util.*;
public class NavigationCameraLaneTest {
    private Router.Route straight(){Graph.Node[] n={new Graph.Node(44,26,""),new Graph.Node(44,26.1,""),new Graph.Node(44,26.2,"")};Graph.Edge[] e={new Graph.Edge(0,1,1,"Highway","motorway",0,0,0,0,0,0,100),new Graph.Edge(1,2,2,"Highway","motorway",0,0,0,0,0,0,100)};Graph g=new Graph("Original fixture","","",true,n,e,List.of());Router.Route r=new Router.Route(g,Arrays.asList(e),new TreeMap<>(),600);r.navigation=new NavigationData(new NavigationData.Road[]{new NavigationData.Road("Highway","motorway",100,true),new NavigationData.Road("Highway","motorway",100,true)},List.of());return r;}
    @Test public void speedAndUpcomingSituationsChangeZoom(){Router.Route r=straight();assertTrue(NavigationCamera.zoom(r,0,10)>NavigationCamera.zoom(r,0,100)+1);NavigationData.Event junction=new NavigationData.Event(400,"split","Fork",List.of(),new int[0]);r.navigation=new NavigationData(new NavigationData.Road[0],List.of(junction));assertTrue(NavigationCamera.zoom(r,0,100)>=17);assertTrue(NavigationCamera.zoom(r,500,100)<17);}
    @Test public void fourLaneSplitPreparesCurrentLaneThreeForFutureLaneOne(){List<NavigationData.Lane> lanes=List.of(new NavigationData.Lane(8,true,true,true),new NavigationData.Lane(8,true,true,true),new NavigationData.Lane(2,false,false,true),new NavigationData.Lane(2,false,false,true));NavigationData.Event split=new NavigationData.Event(5000,"split","Take left branch",lanes,new int[]{2,1,0,0});assertEquals(3,split.recommendedNumber());assertEquals(1,split.futureNumber());NavigationData data=new NavigationData(new NavigationData.Road[0],List.of(split));assertEquals(1,data.lanePreview(0,500).size());assertEquals(1,data.lanePreview(5010,5000).size());assertTrue(data.lanePreview(5021,5000).isEmpty());}
    @Test public void laneBanOutranksRightmostPreference(){NavigationData.Event e=new NavigationData.Event(10,"junction","Turn",List.of(new NavigationData.Lane(8,true,true,true),new NavigationData.Lane(8,true,true,false)),new int[0]);assertEquals(2,e.recommendedNumber());}
}
